public static Vector2 Displacement(string clip,float seconds){if(clip==null||!Frames.TryGetValue(clip,out var frames))return Vector2.zero;float f=Mathf.Clamp(seconds*60,0,frames.Length-1);int a=Mathf.FloorToInt(f),b=Mathf.Min(frames.Length-1,a+1);return Vector2.Lerp(frames[a],frames[b],f-a);}
public static Vector2 Velocity(string clip,float seconds,float deltaTime=0){if(clip==null||!Frames.TryGetValue(clip,out var frames))return Vector2.zero;float end=(frames.Length-1)/60f;if(seconds<0||seconds>end)return Vector2.zero;float step=deltaTime>0?deltaTime:Time.deltaTime>0?Time.deltaTime:1f/60;float a=Mathf.Max(0,seconds-step),b=Mathf.Min(end,seconds);return b>a?(Displacement(clip,b)-Displacement(clip,a))/(b-a):Vector2.zero;}
